// Generated by _src/build-quote.mjs. Edit _src/quote.html, then rebuild.
// Internal quote calculator for the Sundown team, served at /quote behind a password.
// The page and its net rates live only inside this function, so nothing is public.
// Set QUOTE_PASSWORD (and optionally QUOTE_USER, default "sundown") in Vercel project settings.
const PAGE = "<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<meta name=\"robots\" content=\"noindex, nofollow\">\n<title>Sundown Quote Calculator</title>\n<link rel=\"icon\" type=\"image/svg+xml\" href=\"/favicon.svg\">\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\"><link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n<link href=\"https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&family=Playfair+Display:wght@700;800&display=swap\" rel=\"stylesheet\">\n<style>\n:root{--g:#0B3A1D;--g2:#14532D;--gold:#C98A27;--sand:#F6F2EA;--line:#E7E0D2;--ink:#1c1917;--muted:#6b6560;--bad:#b42318}\n*{box-sizing:border-box}\nbody{margin:0;font-family:Inter,system-ui,sans-serif;background:var(--sand);color:var(--ink);font-size:15px;line-height:1.45}\nheader{background:var(--g);color:#fff;padding:14px 18px;display:flex;align-items:center;justify-content:space-between;gap:12px;position:sticky;top:0;z-index:5}\nheader h1{font-family:'Playfair Display',Georgia,serif;font-size:20px;margin:0}\nheader small{color:#E9B865;font-weight:600;letter-spacing:.08em;text-transform:uppercase;font-size:11px}\n.wrap{max-width:1180px;margin:0 auto;padding:18px;display:grid;grid-template-columns:minmax(0,430px) minmax(0,1fr);gap:18px;align-items:start}\n@media(max-width:900px){.wrap{grid-template-columns:1fr;padding:12px}}\n.card{background:#fff;border:1px solid var(--line);border-radius:16px;padding:18px;margin-bottom:16px}\n.card h2{font-size:13px;letter-spacing:.12em;text-transform:uppercase;color:var(--gold);margin:0 0 12px;font-weight:800}\nlabel{display:block;font-size:12px;font-weight:700;color:var(--g);margin:0 0 4px}\ninput,select{width:100%;padding:10px 11px;border:1px solid #d6d0c4;border-radius:10px;font:inherit;background:#fff;color:var(--ink)}\ninput:focus,select:focus{outline:2px solid var(--gold);border-color:var(--gold)}\n.row{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-bottom:10px}\n.row3{display:grid;grid-template-columns:1fr 1fr 1fr;gap:10px;margin-bottom:10px}\n.f{margin-bottom:10px}\n.hint{font-size:12px;color:var(--muted);margin:4px 0 0}\n.chk{display:flex;gap:8px;align-items:center;font-weight:600;font-size:14px;margin:6px 0}\n.chk input{width:auto}\n.seg{display:flex;gap:6px;flex-wrap:wrap}\n.seg button{flex:1;min-width:120px;padding:9px 10px;border:1px solid #d6d0c4;background:#fff;border-radius:10px;font:inherit;font-size:13px;font-weight:600;cursor:pointer;color:var(--g)}\n.seg button.on{background:var(--g);color:#fff;border-color:var(--g)}\ntable{width:100%;border-collapse:collapse;font-size:14px}\nth,td{text-align:left;padding:8px 6px;border-bottom:1px solid var(--line);vertical-align:top}\nth{font-size:11px;letter-spacing:.08em;text-transform:uppercase;color:var(--muted)}\ntd.n,th.n{text-align:right;white-space:nowrap}\ntr.tot td{font-weight:800;border-top:2px solid var(--g)}\n.big{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px;margin-bottom:14px}\n@media(max-width:560px){.big{grid-template-columns:1fr}}\n.kpi{background:var(--sand);border-radius:12px;padding:12px}\n.kpi small{display:block;font-size:11px;font-weight:700;letter-spacing:.08em;text-transform:uppercase;color:var(--muted)}\n.kpi b{font-size:20px;color:var(--g)}\n.kpi.gold{background:var(--g);color:#fff}.kpi.gold b{color:#E9B865}.kpi.gold small{color:#cfe3d4}\n.warn{background:#fff4e5;border:1px solid #f5c88a;color:#7a4b00;border-radius:12px;padding:10px 12px;font-size:13px;margin-bottom:12px}\n.warn.bad{background:#fdecea;border-color:#f1a7a1;color:var(--bad)}\ntextarea{width:100%;min-height:260px;border:1px solid #d6d0c4;border-radius:12px;padding:12px;font:14px/1.5 Inter,system-ui,sans-serif;resize:vertical}\n.btn{display:inline-flex;align-items:center;gap:8px;background:var(--gold);color:#0d1f16;border:0;border-radius:999px;padding:11px 18px;font:inherit;font-weight:800;cursor:pointer}\n.btn.ghost{background:#fff;border:1px solid var(--line);color:var(--g)}\n.xrow{display:grid;grid-template-columns:1.6fr 1fr .9fr auto;gap:6px;margin-bottom:6px}\n.xrow button{border:0;background:#f3eee4;border-radius:8px;padding:0 10px;cursor:pointer;font-weight:800;color:var(--muted)}\n.muted{color:var(--muted)}\n.rates td{font-size:13px}\n</style>\n</head>\n<body>\n<header><div><small>Sundown Safaris internal</small><h1>Quote calculator</h1></div><span class=\"muted\" style=\"color:#cfe3d4;font-size:12px\" id=\"fxnote\"></span></header>\n<div class=\"wrap\">\n<div>\n  <div class=\"card\">\n    <h2>Trip</h2>\n    <div class=\"f\"><label for=\"lodge\">Lodge</label><select id=\"lodge\"></select></div>\n    <div class=\"row\">\n      <div><label for=\"checkin\">Check in</label><input type=\"date\" id=\"checkin\"></div>\n      <div><label for=\"nights\">Nights</label><input type=\"number\" id=\"nights\" min=\"1\" value=\"1\"></div>\n    </div>\n    <p class=\"hint\" id=\"lodgenote\"></p>\n  </div>\n\n  <div class=\"card\">\n    <h2>Guests (adults)</h2>\n    <div class=\"row3\">\n      <div><label for=\"nCit\">Kenyan citizens</label><input type=\"number\" id=\"nCit\" min=\"0\" value=\"0\"></div>\n      <div><label for=\"nRes\">Residents</label><input type=\"number\" id=\"nRes\" min=\"0\" value=\"0\"></div>\n      <div><label for=\"nNr\">Visitors</label><input type=\"number\" id=\"nNr\" min=\"0\" value=\"2\"></div>\n    </div>\n    <label>Of those, how many want their own single room</label>\n    <div class=\"row3\">\n      <div><input type=\"number\" id=\"sCit\" min=\"0\" value=\"0\" aria-label=\"Citizens in single rooms\"></div>\n      <div><input type=\"number\" id=\"sRes\" min=\"0\" value=\"0\" aria-label=\"Residents in single rooms\"></div>\n      <div><input type=\"number\" id=\"sNr\" min=\"0\" value=\"0\" aria-label=\"Visitors in single rooms\"></div>\n    </div>\n    <p class=\"hint\">Everyone else shares a double or twin. Residents need a work permit or residence ID at check in. Children are not handled here, add them as extras.</p>\n    <label class=\"chk\"><input type=\"checkbox\" id=\"tent\"> Upgrade to the lodge's tents</label>\n  </div>\n\n  <div class=\"card\">\n    <h2>Vehicle and park</h2>\n    <div class=\"row\">\n      <div><label for=\"vDays\">Vehicle days</label><input type=\"number\" id=\"vDays\" min=\"0\" value=\"2\"></div>\n      <div><label for=\"vRate\">Rate per day (KES)</label><input type=\"number\" id=\"vRate\" min=\"0\" value=\"28000\"></div>\n    </div>\n    <div class=\"row\">\n      <div><label for=\"vCount\">Vehicles</label><input type=\"number\" id=\"vCount\" min=\"1\" value=\"1\"></div>\n      <div><label for=\"pDays\">Park days</label><input type=\"number\" id=\"pDays\" min=\"0\" value=\"2\"></div>\n    </div>\n    <p class=\"hint\" id=\"parknote\"></p>\n  </div>\n\n  <div class=\"card\">\n    <h2>Extras</h2>\n    <div id=\"extras\"></div>\n    <button class=\"btn ghost\" type=\"button\" id=\"addx\">Add an extra</button>\n    <p class=\"hint\">Balloon, bush dinner, flights, transfers. Enter your cost in KES, per person or for the whole group.</p>\n  </div>\n\n  <div class=\"card\">\n    <h2>Pricing</h2>\n    <div class=\"row\">\n      <div><label for=\"margin\">Margin on price (%)</label><input type=\"number\" id=\"margin\" min=\"0\" max=\"80\" value=\"20\"></div>\n      <div><label for=\"fx\">KES per USD</label><input type=\"number\" id=\"fx\" step=\"0.01\" value=\"129.5\"></div>\n    </div>\n    <label>Resident room pricing</label>\n    <div class=\"seg\" id=\"mode\">\n      <button type=\"button\" data-v=\"card\" class=\"on\">Sell rooms at card rate, keep commission</button>\n      <button type=\"button\" data-v=\"margin\">Add margin on rooms too</button>\n    </div>\n    <div class=\"row\" style=\"margin-top:10px\">\n      <div><label for=\"roundTo\">Round prices up to (KES)</label><input type=\"number\" id=\"roundTo\" min=\"1\" value=\"500\"></div>\n      <div><label for=\"pickup\">Pickup area (for the quote)</label><input type=\"text\" id=\"pickup\" placeholder=\"Keleshwa\"></div>\n    </div>\n  </div>\n</div>\n\n<div>\n  <div class=\"card\">\n    <h2>Result</h2>\n    <div id=\"alerts\"></div>\n    <div class=\"big\">\n      <div class=\"kpi gold\"><small>Total to client</small><b id=\"kTotal\">KES 0</b><div id=\"kTotalUsd\" style=\"font-size:12px;color:#cfe3d4\"></div></div>\n      <div class=\"kpi\"><small>Your cost</small><b id=\"kCost\">KES 0</b></div>\n      <div class=\"kpi\"><small>Your profit</small><b id=\"kProfit\">KES 0</b><div id=\"kPct\" class=\"muted\" style=\"font-size:12px\"></div></div>\n    </div>\n    <table id=\"prices\"></table>\n  </div>\n\n  <div class=\"card\">\n    <h2>Cost breakdown</h2>\n    <table id=\"breakdown\"></table>\n  </div>\n\n  <div class=\"card\">\n    <h2>WhatsApp quote</h2>\n    <textarea id=\"wa\"></textarea>\n    <div style=\"display:flex;gap:8px;margin-top:10px;flex-wrap:wrap\">\n      <button class=\"btn\" type=\"button\" id=\"copy\">Copy quote</button>\n      <span class=\"hint\" id=\"copied\"></span>\n    </div>\n  </div>\n\n  <div class=\"card\">\n    <h2>Rates loaded</h2>\n    <div id=\"ratelist\"></div>\n  </div>\n</div>\n</div>\n\n<script>\n// ---------------- RATE DATA ----------------\n// Non resident: USD per person per night, full board, net of commission, inclusive of all taxes.\n//   d = per person sharing a double, s = single room per person.\n// Resident: KES per ROOM per night, full board, card rate. Commission is taken off to get your cost.\n// Source: Simba Lodges contract agreements 2026 and 2027, resident rates July to December 2026 and festive 2026.\nvar LODGES = [\n {id:'mara-simba', name:'Mara Simba Lodge', park:'mara', driverRoom:1500, resComm:0.15,\n  pitch:'on the banks of the Talek River, with solid rooms looking over the water',\n  nr:[\n   ['2025-12-16','2026-03-31',221,126],['2026-04-01','2026-05-31',75,75],['2026-06-01','2026-06-30',245,140],\n   ['2026-07-01','2026-10-31',420,240],['2026-11-01','2026-12-15',184,105],\n   ['2026-12-16','2027-03-31',247,141],['2027-04-01','2027-05-31',90,90],['2027-06-01','2027-06-30',272,155],\n   ['2027-07-01','2027-10-31',447,255],['2027-11-01','2027-12-15',210,120]],\n  res:[\n   ['2026-07-01','2026-07-20',29000,37000],['2026-07-21','2026-08-20',45000,66000],['2026-08-21','2026-08-31',29000,37000],\n   ['2026-09-01','2026-12-23',20000,26000],['2026-12-24','2026-12-26',25000,40000],['2026-12-27','2026-12-30',22000,30000],\n   ['2026-12-31','2027-01-01',25000,40000]],\n  tentNr:50, tentRes:4000},\n {id:'naivasha-simba', name:'Lake Naivasha Simba Lodge', park:'naivasha', driverRoom:1000, resComm:0.15,\n  pitch:'on the shores of Lake Naivasha, with gardens where giraffe and zebra wander',\n  nr:[\n   ['2025-12-16','2026-03-31',228,130],['2026-04-01','2026-05-31',184,105],['2026-06-01','2026-06-30',245,140],\n   ['2026-07-01','2026-10-31',385,220],['2026-11-01','2026-12-15',228,130],\n   ['2026-12-16','2027-03-31',245,140],['2027-04-01','2027-05-31',202,115],['2027-06-01','2027-06-30',245,140],\n   ['2027-07-01','2027-10-31',412,235],['2027-11-01','2027-12-15',245,140]],\n  res:[\n   ['2026-07-01','2026-08-15',29500,38000],['2026-08-16','2026-08-31',32000,42000],['2026-09-01','2026-10-15',27000,33000],\n   ['2026-10-16','2026-10-31',27000,35500],['2026-11-01','2026-12-23',22000,30000],['2026-12-24','2026-12-26',26000,41000],\n   ['2026-12-27','2026-12-30',23000,33000],['2026-12-31','2027-01-01',26000,41000]],\n  tentNr:0, tentRes:0, minFestive:'Minimum 2 nights over 24 to 26 December.'},\n {id:'samburu-simba', name:'Samburu Simba Lodge', park:'samburu', driverRoom:1500, resComm:0.15,\n  pitch:'in Samburu, home of the rare northern species you will not see in the Mara',\n  nr:[\n   ['2025-12-16','2026-03-31',167,95],['2026-04-01','2026-06-30',75,75],['2026-07-01','2026-10-31',202,115],\n   ['2026-11-01','2026-12-15',167,95],\n   ['2026-12-16','2027-03-31',167,95],['2027-04-01','2027-06-30',75,75],['2027-07-01','2027-10-31',202,115],\n   ['2027-11-01','2027-12-15',167,95]],\n  res:[\n   ['2026-07-01','2026-07-31',19000,27500],['2026-08-01','2026-08-31',16000,22000],['2026-09-01','2026-12-23',15000,20500],\n   ['2026-12-24','2026-12-26',20000,28000],['2026-12-27','2026-12-30',16000,22000],['2026-12-31','2027-01-01',20000,28000]],\n  tentNr:0, tentRes:0}\n];\nvar XMAS_NR = 35; // USD per adult per night, 24 Dec to 1 Jan, non residents\n// Park fees per adult per day. Mara: masaimara.travel, Jan to Jun and Jul to Dec rates. Samburu: samburureserve.com, 2026.\nvar PARKS = {\n mara:{name:'Masai Mara National Reserve', cit:[1500,3000], res:[2500,5000], nr:[100,200], veh:1000, note:'Mara fees: citizens KES 1,500 or 3,000, residents KES 2,500 or 5,000, visitors USD 100 or 200 per day (January to June, July to December). Vehicle KES 1,000 per entry.'},\n samburu:{name:'Samburu National Reserve', cit:[800,800], res:[1600,1600], nr:[85,85], veh:1600, note:'Samburu fees: citizens KES 800, residents KES 1,600, visitors USD 85 per day. Vehicle KES 1,600 per entry.'},\n naivasha:{name:'Lake Naivasha', cit:[0,0], res:[0,0], nr:[0,0], veh:0, note:'No park fee at Lake Naivasha. Add Hell’s Gate, Crescent Island or boat rides as extras.'}\n};\n\n// ---------------- HELPERS ----------------\nvar $=function(id){return document.getElementById(id)};\nfunction num(id){var v=parseFloat($(id).value);return isNaN(v)?0:v}\nfunction ds(d){return d.toISOString().slice(0,10)}\nfunction addDays(s,n){var d=new Date(s+'T00:00:00Z');d.setUTCDate(d.getUTCDate()+n);return ds(d)}\nfunction find(rows,date){for(var i=0;i<rows.length;i++){if(date>=rows[i][0]&&date<=rows[i][1])return rows[i]}return null}\nfunction kes(v){return 'KES '+Math.round(v).toLocaleString('en-US')}\nfunction usd(v){return 'USD '+Math.round(v).toLocaleString('en-US')}\nfunction niceDate(s){var d=new Date(s+'T00:00:00Z');return d.toLocaleDateString('en-GB',{weekday:'long',day:'numeric',month:'long',timeZone:'UTC'})}\nfunction shortDate(s){var d=new Date(s+'T00:00:00Z');return d.toLocaleDateString('en-GB',{day:'numeric',month:'long',timeZone:'UTC'})}\nfunction isXmas(date){var md=date.slice(5);return md>='12-24'||md<='01-01'}\nfunction halfIdx(date){return parseInt(date.slice(5,7),10)<=6?0:1}\nfunction esc(s){return String(s).replace(/[&<>\"]/g,function(c){return{'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;'}[c]})}\n\nvar MODE='card';\nvar LABEL={cit:'Kenyan citizen',res:'resident',nr:'visitor'};\nvar LABELS={cit:'Kenyan citizens',res:'residents',nr:'visitors'};\n\n// ---------------- CALCULATION ----------------\nfunction calc(){\n var L=LODGES.filter(function(x){return x.id===$('lodge').value})[0];\n var P=PARKS[L.park];\n var checkin=$('checkin').value, nights=Math.max(1,num('nights')), fx=num('fx')||129.5;\n var m=Math.min(0.8,Math.max(0,num('margin')/100)), roundTo=Math.max(1,num('roundTo'));\n var tent=$('tent').checked;\n var alerts=[];\n var cats=['cit','res','nr'];\n var cnt={cit:num('nCit'),res:num('nRes'),nr:num('nNr')};\n var sgl={cit:Math.min(num('sCit'),cnt.cit),res:Math.min(num('sRes'),cnt.res),nr:Math.min(num('sNr'),cnt.nr)};\n var total=cnt.cit+cnt.res+cnt.nr;\n if(!checkin){alerts.push(['bad','Pick a check in date.']);}\n if(total<1){alerts.push(['bad','Add at least one guest.']);}\n var sharers=total-sgl.cit-sgl.res-sgl.nr;\n if(sharers%2===1)alerts.push(['','An odd number of guests are sharing, so one double room has one person. Move someone to a single room or check the room setup.']);\n if(tent&&!L.tentNr&&!L.tentRes)alerts.push(['','This lodge has no tent supplement on its card. Tent upgrade ignored.']);\n if(L.minFestive&&checkin){for(var q=0;q<nights;q++){var dq=addDays(checkin,q);if(dq.slice(5)>='12-24'&&dq.slice(5)<='12-26'&&nights<2){alerts.push(['',L.minFestive]);break}}}\n\n // groups: category x room type\n var groups=[];\n cats.forEach(function(c){var s=sgl[c],d=cnt[c]-s;if(d>0)groups.push({c:c,room:'double',n:d});if(s>0)groups.push({c:c,room:'single',n:s})});\n\n // lodge cost per person per group\n var missing={};\n groups.forEach(function(g){\n  g.lodgeNet=0;g.lodgeCard=0;\n  if(!checkin)return;\n  for(var i=0;i<nights;i++){\n   var date=addDays(checkin,i);\n   if(g.c==='nr'){\n    var r=find(L.nr,date);\n    if(!r){missing['Visitor rate for '+shortDate(date)]=1;continue}\n    var pp=(g.room==='single'?r[2]:r[3]);\n    if(isXmas(date))pp+=XMAS_NR;\n    if(tent&&L.tentNr)pp+=L.tentNr;\n    g.lodgeNet+=pp*fx;g.lodgeCard+=pp*fx;\n   }else{\n    var rr=find(L.res,date);\n    if(!rr){missing['Resident rate for '+shortDate(date)]=1;continue}\n    var card=(g.room==='single'?rr[2]:rr[3]/2);\n    var net=card*(1-L.resComm);\n    if(tent&&L.tentRes){net+=L.tentRes;card+=L.tentRes}\n    g.lodgeNet+=net;g.lodgeCard+=card;\n   }\n  }\n });\n Object.keys(missing).forEach(function(k){alerts.push(['bad','No '+k+' at '+L.name+'. Load the rate card for these dates before quoting.'])});\n\n // park fees per person\n var pDays=Math.max(0,num('pDays'));\n groups.forEach(function(g){\n  g.park=0;if(!checkin)return;\n  for(var j=0;j<pDays;j++){var dt=addDays(checkin,j),h=halfIdx(dt);\n   g.park+= g.c==='nr'? P.nr[h]*fx : P[g.c][h];}\n });\n\n // shared costs\n var vCount=Math.max(1,num('vCount')), vDays=Math.max(0,num('vDays')), vRate=num('vRate');\n var shared=[];\n shared.push(['Vehicle, guide and fuel ('+vDays+' days x '+kes(vRate)+(vCount>1?' x '+vCount+' vehicles':'')+')',vDays*vRate*vCount]);\n shared.push(['Driver room and meals ('+nights+' nights x '+kes(L.driverRoom)+(vCount>1?' x '+vCount:'')+')',nights*L.driverRoom*vCount]);\n if(P.veh&&pDays)shared.push(['Vehicle gate fee ('+pDays+' days x '+kes(P.veh)+(vCount>1?' x '+vCount:'')+')',pDays*P.veh*vCount]);\n var xper=0;\n document.querySelectorAll('.xrow').forEach(function(r){\n  var lab=r.querySelector('.xl').value||'Extra',amt=parseFloat(r.querySelector('.xa').value)||0,mode=r.querySelector('.xm').value;\n  if(!amt)return;\n  if(mode==='pp'){xper+=amt;shared.push([lab+' ('+kes(amt)+' per person)',amt*total])}\n  else shared.push([lab,amt]);\n });\n var sharedTotal=shared.reduce(function(a,b){return a+b[1]},0);\n var sharedPP= total? sharedTotal/total : 0;\n\n // pricing per group\n var totCost=0,totPrice=0;\n groups.forEach(function(g){\n  g.cost=g.lodgeNet+g.park+sharedPP;\n  var other=g.park+sharedPP;\n  var raw;\n  if(g.c!=='nr'&&MODE==='card') raw=g.lodgeCard+other/(1-m);\n  else raw=g.cost/(1-m);\n  g.price=Math.ceil(raw/roundTo)*roundTo;\n  totCost+=g.cost*g.n;totPrice+=g.price*g.n;\n });\n var profit=totPrice-totCost;\n\n // ---------- render ----------\n $('alerts').innerHTML=alerts.map(function(a){return '<div class=\"warn '+a[0]+'\">'+esc(a[1])+'</div>'}).join('');\n $('kTotal').textContent=kes(totPrice);$('kTotalUsd').textContent=usd(totPrice/fx);\n $('kCost').textContent=kes(totCost);$('kProfit').textContent=kes(profit);\n $('kPct').textContent=totPrice?Math.round(profit/totPrice*100)+'% of the price':'';\n var ph='<tr><th>Guests</th><th class=\"n\">Cost each</th><th class=\"n\">Price each</th><th class=\"n\">USD each</th><th class=\"n\">Subtotal</th></tr>';\n groups.forEach(function(g){ph+='<tr><td>'+g.n+' '+(g.n>1?LABELS[g.c]:LABEL[g.c])+(g.room==='single'?', own room':', sharing')+'</td><td class=\"n\">'+kes(g.cost)+'</td><td class=\"n\"><b>'+kes(g.price)+'</b></td><td class=\"n\">'+usd(g.price/fx)+'</td><td class=\"n\">'+kes(g.price*g.n)+'</td></tr>'});\n ph+='<tr class=\"tot\"><td>Total</td><td class=\"n\">'+kes(totCost)+'</td><td></td><td class=\"n\">'+usd(totPrice/fx)+'</td><td class=\"n\">'+kes(totPrice)+'</td></tr>';\n $('prices').innerHTML=ph;\n\n var bh='<tr><th>Item</th><th class=\"n\">Your cost</th></tr>';\n groups.forEach(function(g){\n  bh+='<tr><td>'+L.name+', '+nights+' night'+(nights>1?'s':'')+', '+g.n+' '+(g.n>1?LABELS[g.c]:LABEL[g.c])+(g.room==='single'?' in single rooms':' sharing')+(g.c!=='nr'?' (card '+kes(g.lodgeCard*g.n)+', less '+Math.round(L.resComm*100)+'% commission)':' (net USD rate)')+(tent&&(L.tentNr||L.tentRes)?', tents':'')+'</td><td class=\"n\">'+kes(g.lodgeNet*g.n)+'</td></tr>';\n });\n groups.forEach(function(g){if(g.park)bh+='<tr><td>Park fees, '+pDays+' days, '+g.n+' '+(g.n>1?LABELS[g.c]:LABEL[g.c])+'</td><td class=\"n\">'+kes(g.park*g.n)+'</td></tr>'});\n shared.forEach(function(s){bh+='<tr><td>'+esc(s[0])+'</td><td class=\"n\">'+kes(s[1])+'</td></tr>'});\n bh+='<tr class=\"tot\"><td>Total cost</td><td class=\"n\">'+kes(totCost)+'</td></tr>';\n $('breakdown').innerHTML=bh;\n $('lodgenote').textContent='Rooms from 12 noon, checkout by 10am. Driver room '+kes(L.driverRoom)+' a night.'+(L.minFestive?' '+L.minFestive:'');\n $('parknote').textContent=P.note;\n\n // WhatsApp quote\n var t='';\n if(checkin&&total){\n  var out=addDays(checkin,nights), pick=$('pickup').value.trim()||'Nairobi';\n  t+='Here is your '+(L.park==='mara'?'Masai Mara':L.park==='samburu'?'Samburu':'Lake Naivasha')+' safari, '+niceDate(checkin)+' to '+niceDate(out)+'.\\n\\n';\n  t+=L.name+' sits '+L.pitch+'.\\n\\n';\n  t+='The plan\\n';\n  t+='Day 1, pickup from '+pick+' in the morning in your own Land Cruiser with your guide, lunch at the lodge and an afternoon game drive.\\n';\n  if(nights>1)t+='Days 2 to '+nights+', full days on safari with your guide, at your own pace.\\n';\n  t+='Last day, an early game drive or a relaxed breakfast, then the drive home to '+pick+'.\\n\\n';\n  t+='Included\\nPrivate Land Cruiser and guide, fuel, '+nights+' night'+(nights>1?'s':'')+' full board'+(tent&&(L.tentNr||L.tentRes)?' in the lodge tents':'')+(P.veh||P.nr[1]?', park fees':'')+' and bottled water';\n  var xl=[];document.querySelectorAll('.xrow').forEach(function(r){var v=r.querySelector('.xl').value;if(v&&parseFloat(r.querySelector('.xa').value))xl.push(v.toLowerCase())});\n  if(xl.length)t+=', plus '+xl.join(', ');\n  t+='.\\n\\nPrice\\n';\n  if(groups.length===1){t+=kes(groups[0].price)+' per person\\n'}else groups.forEach(function(g){t+=kes(g.price)+' per person for '+(g.n>1?'the '+g.n+' '+LABELS[g.c]:'the '+LABEL[g.c])+(g.room==='single'?' in their own room':'')+'\\n'});\n  if(groups.length>1||total>1)t+=kes(totPrice)+' in total for '+(total===2?'the two of you':'all '+total+' of you')+'\\n';\n  t+='\\nShall I go ahead and hold it for you?';\n }\n $('wa').value=t;\n try{localStorage.setItem('sdq',JSON.stringify(state()))}catch(e){}\n}\n\n// ---------------- UI ----------------\nvar FIELDS=['lodge','checkin','nights','nCit','nRes','nNr','sCit','sRes','sNr','vDays','vRate','vCount','pDays','margin','fx','roundTo','pickup'];\nfunction state(){var s={mode:MODE,tent:$('tent').checked,x:[]};FIELDS.forEach(function(f){s[f]=$(f).value});document.querySelectorAll('.xrow').forEach(function(r){s.x.push([r.querySelector('.xl').value,r.querySelector('.xa').value,r.querySelector('.xm').value])});return s}\nfunction addExtra(l,a,mo){var d=document.createElement('div');d.className='xrow';d.innerHTML='<input class=\"xl\" placeholder=\"Balloon flight\"><input class=\"xa\" type=\"number\" min=\"0\" placeholder=\"KES\"><select class=\"xm\"><option value=\"pp\">per person</option><option value=\"all\">for group</option></select><button type=\"button\" aria-label=\"Remove\">x</button>';d.querySelector('.xl').value=l||'';d.querySelector('.xa').value=a||'';d.querySelector('.xm').value=mo||'pp';d.querySelector('button').onclick=function(){d.remove();calc()};d.addEventListener('input',calc);d.addEventListener('change',calc);$('extras').appendChild(d)}\nLODGES.forEach(function(l){var o=document.createElement('option');o.value=l.id;o.textContent=l.name;$('lodge').appendChild(o)});\n// rate list\n(function(){var h='';LODGES.forEach(function(l){h+='<p style=\"margin:10px 0 4px\"><b>'+l.name+'</b> <span class=\"muted\">visitor rates '+l.nr[0][0]+' to '+l.nr[l.nr.length-1][1]+', resident rates '+l.res[0][0]+' to '+l.res[l.res.length-1][1]+', commission '+Math.round(l.resComm*100)+'% on resident adults</span></p>'});h+='<p class=\"hint\">Visitor rates are net USD per person, inclusive of taxes. Christmas supplement USD 35 per visitor per night from 24 December to 1 January. Resident rates are card rates per room. Source: Simba Lodges contracts 2026 and 2027.</p>';$('ratelist').innerHTML=h})();\ndocument.querySelectorAll('#mode button').forEach(function(b){b.onclick=function(){MODE=b.dataset.v;document.querySelectorAll('#mode button').forEach(function(x){x.classList.toggle('on',x===b)});calc()}});\n$('addx').onclick=function(){addExtra();};\n$('nights').addEventListener('input',function(){var n=Math.max(1,num('nights'));$('vDays').value=n+1;$('pDays').value=n+1;});\ndocument.querySelectorAll('input,select').forEach(function(el){el.addEventListener('input',calc);el.addEventListener('change',calc)});\n$('copy').onclick=function(){var t=$('wa');t.select();try{navigator.clipboard.writeText(t.value).then(function(){$('copied').textContent='Copied'})}catch(e){document.execCommand('copy');$('copied').textContent='Copied'}};\n// restore\ntry{var s=JSON.parse(localStorage.getItem('sdq')||'null');if(s){FIELDS.forEach(function(f){if(s[f]!=null)$(f).value=s[f]});$('tent').checked=!!s.tent;MODE=s.mode||'card';document.querySelectorAll('#mode button').forEach(function(x){x.classList.toggle('on',x.dataset.v===MODE)});(s.x||[]).forEach(function(x){addExtra(x[0],x[1],x[2])})}}catch(e){}\nif(!$('checkin').value){var d=new Date();d.setDate(d.getDate()+((6-d.getDay()+7)%7||7));$('checkin').value=d.toISOString().slice(0,10)}\n// live KES rate\nfetch('/api/fx').then(function(r){return r.json()}).then(function(j){if(j&&j.rates&&j.rates.KES){$('fxnote').textContent='Live rate today: KES '+j.rates.KES.toFixed(2)+' per USD';if(!localStorage.getItem('sdq_fx_manual')){$('fx').value=j.rates.KES.toFixed(2);calc()}}}).catch(function(){});\n$('fx').addEventListener('input',function(){try{localStorage.setItem('sdq_fx_manual','1')}catch(e){}});\ncalc();\n</script>\n</body>\n</html>\n";
export const config = { runtime: 'edge' };

function deny() {
  return new Response('Sundown team only', {
    status: 401,
    headers: {
      'WWW-Authenticate': 'Basic realm="Sundown quote tool", charset="UTF-8"',
      'cache-control': 'no-store',
      'x-robots-tag': 'noindex, nofollow'
    }
  });
}

function same(a, b) {
  if (a.length !== b.length) return false;
  let diff = 0;
  for (let i = 0; i < a.length; i++) diff |= a.charCodeAt(i) ^ b.charCodeAt(i);
  return diff === 0;
}

export default async function handler(request) {
  const pass = process.env.QUOTE_PASSWORD || '';
  const user = process.env.QUOTE_USER || 'sundown';
  if (!pass) return deny();
  const auth = request.headers.get('authorization') || '';
  if (!auth.startsWith('Basic ')) return deny();
  let decoded = '';
  try { decoded = atob(auth.slice(6)); } catch (e) { return deny(); }
  const i = decoded.indexOf(':');
  if (i < 0) return deny();
  if (!same(decoded.slice(0, i), user) || !same(decoded.slice(i + 1), pass)) return deny();
  return new Response(PAGE, {
    headers: {
      'content-type': 'text/html; charset=utf-8',
      'cache-control': 'private, no-store',
      'x-robots-tag': 'noindex, nofollow',
      'x-frame-options': 'DENY'
    }
  });
}
